import{_ as i,C as r,o,c as s,a9 as t,E as n}from"./chunks/framework.asyjyako.js";const f=JSON.parse('{"title":"PerfChecker Studio in VS Code","description":"","frontmatter":{},"headers":[],"relativePath":"interfaces/vscode.md","filePath":"interfaces/vscode.md","lastUpdated":null}'),l={name:"interfaces/vscode.md"};function d(c,e,h,p,g,u){const a=r("DocMedia");return o(),s("div",null,[e[0]||(e[0]=t('<h1 id="PerfChecker-Studio-in-VS-Code" tabindex="-1">PerfChecker Studio in VS Code <a class="header-anchor" href="#PerfChecker-Studio-in-VS-Code" aria-label="Permalink to &quot;PerfChecker Studio in VS Code {#PerfChecker-Studio-in-VS-Code}&quot;">​</a></h1><p>PerfChecker combines Julia performance tests, saved results, plots and optional agent conversations inside VS Code. <strong>Studio opens as a full editor tab</strong>: keep it beside your source, move it into another editor group, or return to the compact PerfChecker views in the activity bar.</p><p>Follow this page for a first measurement and a version comparison. Continue with <a href="./vscode-configuration">configuration</a>, <a href="./vscode-workflows">plots and Julia tools</a> or <a href="./../mcp-advisor">MCP advice and implementation</a> when you reach those steps.</p><p>The screenshots below show the <strong>actual V1 extension webviews running in an isolated Chromium test harness</strong>, with demonstration projects and results. They are not drawings or screenshots of a complete VS Code window. In VS Code, the same webviews open in editor tabs; the surrounding editor and theme may differ. Select any screenshot to open its full-resolution image, including the form fields and implementation diff.</p><h2 id="Install-and-prepare" tabindex="-1">Install and prepare <a class="header-anchor" href="#Install-and-prepare" aria-label="Permalink to &quot;Install and prepare {#Install-and-prepare}&quot;">​</a></h2><ol><li><p>Install VS Code <strong>1.96 or newer</strong> and Julia <strong>1.10 or newer</strong>.</p></li><li><p>Install <a href="https://marketplace.visualstudio.com/items?itemName=mirage-interactive-fr.perfchecker-vscode" target="_blank" rel="noreferrer">PerfChecker from the Visual Studio Marketplace</a>, or search the Extensions view for <code>@id:mirage-interactive-fr.perfchecker-vscode</code>. You can also download the <a href="https://github.com/Mirage-Interactive-Fr/PerfCheckerVSCode/releases/download/v1.0.0/perfchecker-vscode-1.0.0.vsix" target="_blank" rel="noreferrer">qualified V1 VSIX</a> and use <strong>Extensions → … → Install from VSIX…</strong>. Reload VS Code if prompted. See <a href="https://code.visualstudio.com/docs/configure/extensions/extension-marketplace" target="_blank" rel="noreferrer">VS Code&#39;s installation instructions</a> for either route.</p></li><li><p>Open the package folder. Trust the workspace when you are prepared to execute its Julia code.</p></li><li><p>Prepare a Julia controller environment containing the matching PerfChecker build and the collectors you intend to use. Existing TestItems also require TestItemRunner and the package&#39;s test dependencies.</p></li><li><p>Set <strong>PerfChecker: Runner Project</strong> (<code>perfchecker.runnerProject</code>) to the controller environment. For shared scenarios, set <strong>Scenario Project</strong> (<code>perfchecker.scenarioProject</code>) to the environment containing the measured code and its dependencies.</p></li><li><p>Run <strong>PerfChecker: Open Studio</strong> from the command palette. In a workspace with several folders, select the package to inspect.</p></li></ol><p>The <a href="https://github.com/Mirage-Interactive-Fr/PerfCheckerVSCode/releases/tag/v1.0.0" target="_blank" rel="noreferrer">extension release notes</a> identify the qualified artifact. PerfChecker&#39;s Julia registry release and its VS Code extension are distributed separately; installing the Julia package does not install the extension.</p><p>Opening Studio reads configuration and presents actions. It does not install packages, start Julia, download a model or launch an agent. A controller should contain <code>HTTP</code> if you enable MCP. JET and other analyzers belong in the environment selected for their workers.</p>',8)),n(a,{src:"/assets/screenshots/vscode-studio.png",alt:"PerfChecker V1 Studio webview rendered in Chromium, with the selected Example package and actions for suites, results, Julia tests and agent chat",caption:"Start here: check the selected package and expand Workspace environment to inspect its controller, then choose an action. This is the running extension webview with a demonstration workspace."}),e[1]||(e[1]=t(`<p>If this is your first setup, follow <a href="/PerfChecker/dev/interfaces/vscode-configuration#Prepare-a-controller">Prepare a controller</a> before running an item. Use the dedicated controller so adding a profiler or MCP client does not change your package&#39;s normal dependency environment.</p><p>See <a href="./../guide/installation">Installation</a> for the core and interface packages, and <a href="./vscode-configuration">VS Code configuration</a> for complete settings and environment examples.</p><h2 id="Get-a-first-result" tabindex="-1">Get a first result <a class="header-anchor" href="#Get-a-first-result" aria-label="Permalink to &quot;Get a first result {#Get-a-first-result}&quot;">​</a></h2><p>For a project using <code>@testitem</code>:</p><ol><li><p>Studio → <strong>Existing Julia tests</strong>, or command palette → <strong>PerfChecker: Discover existing test items</strong>.</p></li><li><p>Open VS Code&#39;s <strong>Testing</strong> view and expand the PerfChecker controller named for your selected folder.</p></li><li><p>Select one item and run it. PerfChecker measures the selected item in a fresh worker.</p></li><li><p>Inspect the item&#39;s Testing output for measured milliseconds, sample count and correctness. The summary includes setup and assertions; it does not compare a performance budget.</p></li><li><p>Open <strong>View → Output</strong> and select <strong>PerfChecker test items</strong>. Follow the <code>Evidence:</code> file path to inspect the JSON report&#39;s item validation and each sample&#39;s <code>seconds</code>, <code>bytes</code> and <code>correctness</code>.</p></li></ol><p>If your package has no test items yet, add a small correctness-checked example to <code>test/performance.jl</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TestItems</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@testitem</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Vector reduction&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tags </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:performance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">begin</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    data </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> collect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10_000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    @test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50_005_000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><p>Save the file, discover again and select <strong>Vector reduction</strong>. The item measures its setup and assertion as well as the reduction; use a <a href="./../shared-scenarios">shared scenario</a> when you want prepared inputs outside the measurement. The ordinary <code>performance</code> tag is an example filter, not a required or special tag. The package must have <code>TestItems</code> available for its test declarations.</p><p>The Testing session&#39;s elapsed time can include worker startup. Each item&#39;s reported measured duration has its own boundary. A green functional test does not establish a performance budget. Use <a href="./../test-items">TestItems and tags</a> to distinguish shared, functional-only and performance-only items.</p><p>Native TestItem JSON is a separate result from a suite report. The extension&#39;s <strong>Open visual output</strong> reads saved suite measurements; prepare and run a suite for the distribution, profile and version-series workflow below.</p><p>For a suite, use <strong>PerfChecker: Create feature suite</strong> if you need a starter, or configure your existing <code>perf/suite.jl</code>. Studio → <strong>Feature suite</strong> opens the full visual editor. Select a workload, checks and a target, run that selection, then open the resulting report.</p><h2 id="Work-across-the-full-editor" tabindex="-1">Work across the full editor <a class="header-anchor" href="#Work-across-the-full-editor" aria-label="Permalink to &quot;Work across the full editor {#Work-across-the-full-editor}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Surface</th><th style="text-align:right;">Purpose</th></tr></thead><tbody><tr><td style="text-align:right;">Studio</td><td style="text-align:right;">Start the workflow, inspect the selected project and open the next action</td></tr><tr><td style="text-align:right;">Suite designer</td><td style="text-align:right;">Choose features, checks, targets and comparisons</td></tr><tr><td style="text-align:right;">Testing view</td><td style="text-align:right;">Discover and run existing Julia TestItems</td></tr><tr><td style="text-align:right;">Visual output</td><td style="text-align:right;">Inspect saved distributions, allocations, flame graphs and version comparisons</td></tr><tr><td style="text-align:right;">Investigations</td><td style="text-align:right;">Discover scenarios, measure, diagnose and read deterministic advice</td></tr><tr><td style="text-align:right;">Advisor chat</td><td style="text-align:right;">Discuss saved evidence; explicitly request implementation and review its diff</td></tr><tr><td style="text-align:right;">Julia notebook</td><td style="text-align:right;">Run an editable discovery → measurement → diagnosis workflow</td></tr><tr><td style="text-align:right;">PerfChecker terminal</td><td style="text-align:right;">Use a dedicated Julia session in the controller project</td></tr></tbody></table><p>These are VS Code editor tabs and native surfaces. Arrange them with VS Code&#39;s editor groups; the activity bar is an entry point, not the available working area.</p><h2 id="Design-a-suite-and-compare-targets" tabindex="-1">Design a suite and compare targets <a class="header-anchor" href="#Design-a-suite-and-compare-targets" aria-label="Permalink to &quot;Design a suite and compare targets {#Design-a-suite-and-compare-targets}&quot;">​</a></h2><p>The suite editor supports global and per-feature check selection, version ranges, filtering, sorting and ordering. Name targets for a branch, tag, commit, working tree or release, then choose exact or grouped baselines. Grouped references can use median, mean, minimum or maximum aggregation.</p><p>Save the selection with <strong>Save configuration</strong> in the suite editor. The default is <code>perf/perfchecker-ui.json</code>; compatible web and documentation interfaces can read the same configuration. In extension 1.0.0, the separate command-palette action <strong>PerfChecker: Save shared UI configuration</strong> has a confirmed defect; use the editor button while its correction is being prepared. Running the selection shows progress and leaves saved evidence for later review.</p><p>The editor separates filtering from selection. Search, package/target filters and release bounds change what is visible without deselecting hidden runs. <strong>Select visible</strong> and <strong>Clear visible</strong> act on the current filter; <strong>Clear selection</strong> affects the entire selection. The counter reports selected runs, visible runs and selected runs outside the filter. <strong>Run N selected</strong> includes those hidden selections, so review the exact identifier preview before execution. <strong>Show more</strong> pages workload groups without restricting bulk selection.</p><p>Collector toggles select or deselect matching runs. Unavailable conditions show their reason. Add targets from discovered branches, tags and recent commits or enter a supported ref/URL, then inspect the comparison matrix. Missing or overlapping references are reported before a run; refreshing the plan preserves existing selections when their identifiers still exist.</p>`,19)),n(a,{src:"/assets/screenshots/vscode-suite-designer.png",alt:"Running PerfChecker V1 suite-designer webview with workload filters, selected check types, target controls and a run-selection summary",caption:"Review the exact runs before executing: filtering controls visibility, while selection controls what will run. The screenshot uses demonstration workloads in the extension's real suite designer."}),e[2]||(e[2]=t('<h3 id="Choose-the-evidence-for-your-question" tabindex="-1">Choose the evidence for your question <a class="header-anchor" href="#Choose-the-evidence-for-your-question" aria-label="Permalink to &quot;Choose the evidence for your question {#Choose-the-evidence-for-your-question}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Question</th><th style="text-align:right;">Start with</th><th style="text-align:right;">Read before selecting</th></tr></thead><tbody><tr><td style="text-align:right;">Did this operation become slower?</td><td style="text-align:right;"><code>benchmark</code> or <code>chairmark</code></td><td style="text-align:right;">Samples, time units, prepared inputs and the same collector for both targets</td></tr><tr><td style="text-align:right;">Which call path uses CPU time?</td><td style="text-align:right;"><code>profile</code></td><td style="text-align:right;">Stack sample weights; an empty capture does not prove zero cost</td></tr><tr><td style="text-align:right;">Where do allocations occur?</td><td style="text-align:right;"><code>profile_alloc</code> or <code>alloc</code></td><td style="text-align:right;">Sampling/source-line scope and measured totals</td></tr><tr><td style="text-align:right;">Why does waiting dominate?</td><td style="text-align:right;"><code>wall_profile</code></td><td style="text-align:right;">Requires Julia 1.12 or newer; task stacks include waits</td></tr><tr><td style="text-align:right;">How much traffic does the operation generate?</td><td style="text-align:right;">A network collector</td><td style="text-align:right;">Reported counters, shared interface or isolated namespace have different attribution</td></tr></tbody></table><p>The designer shows combinations made available by your suite and environment; it does not install a missing collector. See <a href="./../reference/checks">Collectors</a> for every supported check and its interpretation.</p><h3 id="Compare-a-working-change-with-a-known-revision" tabindex="-1">Compare a working change with a known revision <a class="header-anchor" href="#Compare-a-working-change-with-a-known-revision" aria-label="Permalink to &quot;Compare a working change with a known revision {#Compare-a-working-change-with-a-known-revision}&quot;">​</a></h3><ol><li><p>Prepare a suite containing the same workload for both targets.</p></li><li><p>Add a named baseline from a branch, tag or recent commit. Prefer a full commit identifier when you need an unambiguous recorded reference.</p></li><li><p>Add the candidate working tree or another supported revision, and inspect the plan&#39;s resolved target information. A Git target is a version of the measured package; <code>juliaExecutable</code> separately chooses the Julia runtime.</p></li><li><p>Choose an exact baseline for a simple before/after comparison. Use grouped references only when their aggregation answers your question.</p></li><li><p>Select the same checks and inputs for both targets. Inspect selected runs, including any hidden by filters, then run the selection.</p></li><li><p>Open both saved reports and inspect correctness, comparison compatibility and the observations. Retain the baseline until the candidate is validated.</p></li></ol><p>Changing a branch name or editor selection does not manufacture a compatible baseline. The saved evidence records the actual measured configuration.</p><p>The suite tree follows:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>package → feature → check type → target</span></span></code></pre></div><p>Read <a href="./../suites-and-comparisons">Suites and comparisons</a> before interpreting a result across environments or machines. Never infer an improvement from a profile weight alone.</p><h2 id="Investigate-and-verify" tabindex="-1">Investigate and verify <a class="header-anchor" href="#Investigate-and-verify" aria-label="Permalink to &quot;Investigate and verify {#Investigate-and-verify}&quot;">​</a></h2><p>Use <strong>PerfChecker: Open investigations</strong> for shared scenarios. <strong>Discover scenarios from tests</strong> inspects declarations and proposes candidates without executing the target program. Proposed candidates need an explicit factory and correctness oracle before they become measurable cases.</p><p>Measure declared cases, diagnose with available analyzers, and choose <strong>Advise from saved evidence</strong>. Missing analyzers appear as unavailable; they are not installed automatically. After a change, rerun the same correctness checks and compare compatible before/after measurements.</p><p><strong>Run bounded investigation</strong> can select declared experiments within count and time budgets. Optional model selection requires structured MCP replies and <code>advisorInvestigates = true</code>; it remains separate from implementation chat.</p><h2 id="Cancel-a-run-and-wait-for-cleanup" tabindex="-1">Cancel a run and wait for cleanup <a class="header-anchor" href="#Cancel-a-run-and-wait-for-cleanup" aria-label="Permalink to &quot;Cancel a run and wait for cleanup {#Cancel-a-run-and-wait-for-cleanup}&quot;">​</a></h2><p>Use <strong>Cancel</strong> in a suite execution notification, the suite Testing profile, an investigation or a native Testing run. PerfChecker asks the Julia controller to interrupt its current task and finish its cleanup. Accepting that request does not mean cleanup has finished: wait for the final run status. Closing a suite or investigation editor also requests cancellation. A new run stays blocked until the previous controller has closed.</p><p>A clean interruption finishes as cancelled. If cleanup fails, the run finishes as failed; <strong>PerfChecker: Show worker output</strong> contains the cause and any retained private inventory directory. See <a href="./../reference/checks">allocation cleanup</a> before handling leftover traces or recovering an inventory.</p><p>The extension allows <strong>60 seconds</strong> for the controller to finish. If that deadline expires, it forces the controller to stop and displays a warning that cleanup was not confirmed. Detached workers, allocation traces or inventories may remain. Closing VS Code forcibly, an operating-system shutdown or repeated interruption can also prevent cleanup; restarting the extension does not delete old <code>.mem</code> files indiscriminately.</p><p>Cancelling advisor chat or an MCP request stops the local conversation. A remote server or agent may continue working after the local request closes. Review the isolated implementation checkout and checkpoint before applying changes; local cancellation does not prove the remote tool stopped.</p><h2 id="Advice-and-explicit-implementation" tabindex="-1">Advice and explicit implementation <a class="header-anchor" href="#Advice-and-explicit-implementation" aria-label="Permalink to &quot;Advice and explicit implementation {#Advice-and-explicit-implementation}&quot;">​</a></h2><p>Studio → <strong>Talk to your agent</strong> opens <strong>PerfChecker: Chat with performance advisor</strong>. For an authenticated native Codex CLI, choose <strong>Connect Codex CLI</strong>: the extension checks the installation and starts a temporary local MCP connector with separate advice and implementation tools. Follow the <a href="/PerfChecker/dev/mcp-advisor#Connect-an-authenticated-Codex-CLI">qualified Codex recipe</a>, or configure an external MCP advice tool. Choose saved evidence if useful, then ask a question. Chat also works without evidence for configuration and usage questions; the agent is told no measurements were attached.</p><p>Review the answer. You can apply the advice yourself, or explicitly select <strong>Prepare implementation from reviewed advice</strong>. The latter requires the connected Codex implementation tool or a separately configured external tool, and a Git repository with an existing commit.</p><p>Before sending implementation, the extension warns that generated changes may be incorrect. It saves a Git checkpoint of the current on-disk state and prepares an isolated temporary checkout. The agent works there; the original working tree receives no proposed changes until you inspect the diff and select <strong>Apply reviewed implementation changes</strong>. <strong>Restore implementation checkpoint</strong> reverses that applied patch when the repository has not drifted.</p><p>Read the <a href="./../mcp-advisor">MCP guide</a> for configuration, what is transmitted, checkpoint recovery, cancellation and the filesystem-access requirements of the agent tool.</p><h2 id="Julia,-notebooks-and-terminals" tabindex="-1">Julia, notebooks and terminals <a class="header-anchor" href="#Julia,-notebooks-and-terminals" aria-label="Permalink to &quot;Julia, notebooks and terminals {#Julia,-notebooks-and-terminals}&quot;">​</a></h2><p><strong>PerfChecker: Open Julia terminal</strong> creates a terminal named for the package and starts the selected Julia executable with the controller project. <strong>New investigation notebook</strong> opens an untitled Julia notebook containing explicit discovery, measurement and diagnosis cells. It is yours to edit and save; select an available Julia kernel.</p><p><strong>PerfChecker: Debug current Julia file</strong> delegates a saved Julia source file to the installed Julia VS Code debugger. Debugging needs <code>julialang.language-julia</code>. The debugger and notebook kernel are separate from isolated measurement workers; stepping through a program is not a performance measurement.</p><p>See <a href="./vscode-workflows">Plots, notebooks and Julia tools</a> for supported displays, notebook prerequisites and a practical debugging sequence.</p><h2 id="Companion-and-3D-integrations" tabindex="-1">Companion and 3D integrations <a class="header-anchor" href="#Companion-and-3D-integrations" aria-label="Permalink to &quot;Companion and 3D integrations {#Companion-and-3D-integrations}&quot;">​</a></h2><p>A companion extension can open Studio for an explicit workspace URI using <code>perfchecker.openStudioForWorkspace</code>. Existing suite-editor and live-landscape integration commands remain available. They select the requested package folder rather than silently using the first folder in a multi-root workspace.</p><p>This provides the workspace boundary used by the Etendu/Beautiful Landscape integration. PerfChecker does not implement a new 3D renderer; the companion owns its scene and live graphics workflow. Verify its supported extension versions and selected folder before starting a run. <a href="./vscode-workflows">Plots, notebooks and Julia tools</a> describes the command contract.</p><h2 id="Resolve-common-problems" tabindex="-1">Resolve common problems <a class="header-anchor" href="#Resolve-common-problems" aria-label="Permalink to &quot;Resolve common problems {#Resolve-common-problems}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Symptom</th><th style="text-align:right;">Check</th></tr></thead><tbody><tr><td style="text-align:right;">Studio command missing</td><td style="text-align:right;">Installed extension is the current stable version; reload the extension host</td></tr><tr><td style="text-align:right;">Worker cannot import PerfChecker</td><td style="text-align:right;">Runner Project contains the matching package and a <code>Project.toml</code></td></tr><tr><td style="text-align:right;">Analyzer unavailable</td><td style="text-align:right;">Scenario Project contains that analyzer and its target dependencies</td></tr><tr><td style="text-align:right;">No plots</td><td style="text-align:right;">A completed saved report contains the relevant observations/profile artifacts</td></tr><tr><td style="text-align:right;">Chat refuses the configuration</td><td style="text-align:right;">Protocol is <code>mcp_http</code>, response is <code>text</code>, and an advice tool is selected</td></tr><tr><td style="text-align:right;">Implementation cannot proceed</td><td style="text-align:right;">A separate tool is configured; Git/HEAD exists; all buffers are saved</td></tr><tr><td style="text-align:right;">Wrong folder in multi-root workspace</td><td style="text-align:right;">Reopen Studio and select the intended package</td></tr></tbody></table><p>Use <strong>PerfChecker: Show worker output</strong> for execution diagnostics. See <a href="/PerfChecker/dev/interfaces/vscode-configuration#Troubleshooting">configuration troubleshooting</a> and the <a href="/PerfChecker/dev/mcp-advisor#Troubleshooting">MCP failure table</a> for the next checks.</p><h2 id="Recorded-example" tabindex="-1">Recorded example <a class="header-anchor" href="#Recorded-example" aria-label="Permalink to &quot;Recorded example {#Recorded-example}&quot;">​</a></h2>',34)),n(a,{src:"/examples/bibliography/vscode/native-items.png",alt:"Bibliography export workload passed in VS Code while its format API item remains unrun",caption:"Earlier native Testing controller example: one selected Bibliography item executed. This image does not show the Studio or implementation workflow."}),e[3]||(e[3]=t('<p><a id="Run-one-existing-item"></a><a id="Read-the-result-before-comparing-it"></a><a id="Visual-suite-editor"></a><a id="Results"></a><a id="Optional-investigations"></a></p>',1))])}const k=i(l,[["render",d]]);export{f as __pageData,k as default};
